/**
 * Decimal place for pricebook.
 */
export const DecimalPlace = {
    1: 1,
    2: 2,
    3: 3
} as const;

/**
 * Decimal place for pricebook.
 */
export type DecimalPlace = typeof DecimalPlace[keyof typeof DecimalPlace];

/**
 * To check the default pricebook.Allowed values: <code>true</code>,<code>false</code>
 */
export type IsDefault = boolean;

/**
 * Mark up or Mark down to discounts.Allowed values: <code>true</code>,<code>false</code>
 */
export type IsIncrease = boolean;

/**
 * About percentage of discounts
 */
export type Percentage = number;

/**
 * Type of the pricebook.Allowed values: <code>per_item</code>,<code>fixed_percentage</code>
 */
export type PricebookType = string;

/**
 * Applicable only when the price book type is per_item. Allowed values: unit, volume. unit: Uses pricebook_rate. volume: Uses price_brackets. Not applicable for fixed_percentage.
 */
export const PricingScheme = { UNIT: 'unit', VOLUME: 'volume' } as const;

/**
 * Applicable only when the price book type is per_item. Allowed values: unit, volume. unit: Uses pricebook_rate. volume: Uses price_brackets. Not applicable for fixed_percentage.
 */
export type PricingScheme = typeof PricingScheme[keyof typeof PricingScheme];

/**
 * Type of the rounding.Allowed values: <code>no_rounding</code>,<code>round_to_dollor</code>,<code>round_to_dollar_minus_01</code>,<code>round_to_half_dollar</code>,<code>round_to_half_dollar_minus_01</code>
 */
export type RoundingType = string;

/**
 * Whether its sales or purchase type.Allowed values: <code>sales</code>,<code>purchases</code>
 */
export type SalesOrPurchaseType = string;

/**
 * Rate of the price book for the Items
 */
export type PricebookRate = number;

/**
 * Unique ID generated by the server for each pricebook line item
 */
export type PricebookItemId = string;

/**
 * Discount percentage for the line item or volume bracket. The value must include a percent sign. Examples: 5%, 10.5%, 0%.
 */
export type PricebookDiscount = string;

/**
 * Lower bound of the quantity range for a volume bracket.
 */
export type StartQuantity = number;

/**
 * Upper bound of the quantity range for a volume bracket.
 */
export type EndQuantity = number;

/**
 * Represents a single tier in price_brackets for volume pricing. Includes: start_quantity, end_quantity, pricebook_rate, and optional pricebook_discount.
 */
export type PriceBracket = {
    pricebook_item_id?: PricebookItemId;
    start_quantity?: StartQuantity;
    end_quantity?: EndQuantity;
    pricebook_rate?: PricebookRate;
    pricebook_discount?: PricebookDiscount;
};

/**
 * Items included in the price book. Applicable when the price book type is set to per_item.
 */
export type PricebookItems = Array<{
    item_id?: ItemId;
    pricebook_rate?: PricebookRate;
    pricebook_item_id?: PricebookItemId;
    pricebook_discount?: PricebookDiscount;
    pricing_scheme?: PricingScheme;
    /**
     * Collection of volume pricing tiers for a line item when pricing_scheme is volume.
     */
    price_brackets?: Array<PriceBracket>;
}>;

/**
 * List all the pricebook details
 */
export type Pricebook = {
    currency_code?: CurrencyCode;
    currency_id?: CurrencyId;
    decimal_place?: DecimalPlace;
    description?: Description;
    is_default?: IsDefault;
    is_increase?: IsIncrease;
    name?: Name;
    percentage?: Percentage;
    pricebook_rate?: PricebookRate;
    pricebook_id?: PricebookId;
    pricebook_items?: PricebookItems;
    pricebook_type?: PricebookType;
    pricing_scheme?: PricingScheme;
    rounding_type?: RoundingType;
    sales_or_purchase_type?: SalesOrPurchaseType;
    status?: Status;
};

