export type TransactionLockResponse = {
    transaction_lock_id?: TransactionLockId;
    accounting_period_id?: AccountingPeriodId;
    transaction_lock_status?: TransactionLockStatus;
    transaction_lock_date?: TransactionLockDate;
    lock_status?: LockStatus;
    lock_scope?: LockScope;
    lock_scope_formatted?: LockScopeFormatted;
    lock_status_formatted?: LockStatusFormatted;
    partial_lock_number?: PartialLockNumber;
    accounting_period_name?: AccountingPeriodName;
    fiscal_year_name?: FiscalYearName;
    start_date?: StartDate;
    end_date?: EndDate;
    status?: Status;
    is_adjustment_period?: IsAdjustmentPeriod;
    locked_by?: LockedBy;
    user_exceptions?: UserExceptions;
    user_exceptions_count?: UserExceptionsCount;
    account_exceptions?: AccountExceptions;
    account_exceptions_count?: AccountExceptionsCount;
    reason?: Reason;
    active_lock_summary?: ActiveLockSummary;
};

/**
 * ID of the transaction lock.
 */
export type TransactionLockId = string;

/**
 * ID of the accounting period.
 */
export type AccountingPeriodId = string;

/**
 * Status of the transaction lock. Allowed Values: <code>disabled</code>, <code>enabled</code>, <code>enabled_with_logging</code>.
 */
export type TransactionLockStatus = string;

/**
 * Date up to which transactions are locked. [yyyy-MM-dd]
 */
export type TransactionLockDate = string;

/**
 * Lock status of the transaction lock.
 */
export type LockStatus = string;

/**
 * Scope of the lock. Allowed Values: <code>0</code>, <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code>, <code>5</code>.
 */
export type LockScope = number;

/**
 * Formatted display value of the lock scope.
 */
export type LockScopeFormatted = string;

/**
 * Formatted display value of the lock status.
 */
export type LockStatusFormatted = string;

/**
 * Partial lock number for the transaction lock.
 */
export type PartialLockNumber = number;

/**
 * Name of the accounting period.
 */
export type AccountingPeriodName = string;

/**
 * Name of the fiscal year.
 */
export type FiscalYearName = string;

/**
 * Whether the period is an adjustment period.
 */
export type IsAdjustmentPeriod = boolean;

/**
 * Name of the user who locked the period.
 */
export type LockedBy = string;

/**
 * List of users exempted from the transaction lock.
 */
export type UserExceptions = Array<string>;

/**
 * Number of users exempted from the transaction lock.
 */
export type UserExceptionsCount = number;

/**
 * List of accounts exempted from the transaction lock.
 */
export type AccountExceptions = Array<string>;

/**
 * Number of accounts exempted from the transaction lock.
 */
export type AccountExceptionsCount = number;

/**
 * Summary of the active transaction lock.
 */
export type ActiveLockSummary = {
    [key: string]: unknown;
};

/**
 * Module to which the transaction lock applies. Allowed Values: <code>sales</code>, <code>purchase</code>, <code>accountant</code>, <code>banking</code>, <code>inventory_adjustments</code>.
 */
export type TransactionLockModule = string;

/**
 * Whether partial unlock is enabled.
 */
export type IsEnabled = boolean;

/**
 * Module for partial unlock. Allowed Values: <code>all</code>, <code>sales</code>, <code>purchase</code>, <code>accountant</code>, <code>banking</code>.
 */
export type LockModule = string;

